function project(route,p){let best=Infinity,distance=0,sum=0;for(let i=1;i<route.length;i++){const a=route[i-1],b=route[i],dx=b[0]-a[0],dz=b[1]-a[1],length=Math.hypot(dx,dz),t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[2]-a[1])*dz)/(length*length))),near=Math.hypot(p[0]-a[0]-dx*t,p[2]-a[1]-dz*t);if(near<best){best=near;distance=sum+t*length;}sum+=length;}return distance;}
export class ConvoyHUD {
 constructor(root,{onResults=()=>{}}={}){this.root=root;this.onResults=onResults;root.hidden=false;root.innerHTML='<div class="convoy-heading"><b>CONVOY DEFENSE</b><span data-phase></span></div><div class="convoy-route-heading"><span data-progress-label></span><span data-exit-count></span></div><div class="convoy-route" role="progressbar" aria-label="Lead bus route progress" aria-valuemin="0" aria-valuemax="100"><div class="convoy-route-track"><i data-route-fill></i></div><span class="convoy-route-start">START</span><span class="convoy-route-exit">EXIT</span><div data-stops></div><div data-route-buses></div></div><div class="convoy-counts"><span>SAVED <b data-saved>0</b></span><span>KILLED <b data-lost>0</b></span><span>LEFT BEHIND <b data-unsaved>0</b></span><span>WAITING <b data-waiting>0</b></span><span>ABOARD <b data-onboard>0</b></span></div><div data-buses></div><div class="convoy-detail"><small data-detail></small><button data-results hidden>Results</button></div>';root.querySelector('[data-results]').onclick=()=>this.onResults();this.busRows=[];this.busMarkers=[];this.stopMarkers=[];}
 build(mission){const c=mission.config;this.config=c;this.busRows=[];this.busMarkers=[];this.stopMarkers=[];for(const [i,p]of c.map.pickups.entries()){const node=document.createElement('span');node.className='convoy-route-stop';node.style.left=p.distance/mission.length*100+'%';node.textContent=String(i+1);node.title='Pickup '+(i+1)+' — '+p.name;this.root.querySelector('[data-stops]').append(node);this.stopMarkers.push(node);}for(let i=0;i<c.busCount;i++){const row=document.createElement('div');row.className='convoy-bus-health';row.innerHTML='<div>BUS '+(i+1)+' <b data-state></b></div><span data-hp></span><span data-passengers></span><i role="progressbar" aria-valuemin="0" aria-valuemax="100"><em></em></i>';this.root.querySelector('[data-buses]').append(row);this.busRows.push(row);const marker=document.createElement('span');marker.className='convoy-route-bus';marker.textContent=String(i+1);marker.style.top=(23+i*4)+'px';this.root.querySelector('[data-route-buses]').append(marker);this.busMarkers.push(marker);}}
 update(mission){if(!this.config)this.build(mission);const d=mission.diagnostics(),text=(key,value)=>{const node=this.root.querySelector('[data-'+key+']');if(node.textContent!==String(value))node.textContent=value;};for(const key of['saved','lost','unsaved','waiting','onboard'])text(key,d[key]);text('phase',d.phase==='starting'?'DEPARTING IN '+Math.ceil(d.remaining)+'s':d.phase==='pickup'?'PICKUP '+d.pickup+' / 2 · '+Math.ceil(d.remaining)+'s':d.phase==='success'?'EVACUATION COMPLETE':d.phase==='failed'?'ALL BUSES LOST':d.blocked?'ROUTE BLOCKED':'CONVOY MOVING');
  const progress=Math.max(0,Math.min(100,d.distance/d.routeLength*100));text('progress-label','LEAD ROUTE · '+Math.floor(progress)+'%');text('exit-count',d.buses.filter(b=>b.escaped).length+'/'+d.buses.length+' BUSES SAFE');this.root.querySelector('[data-route-fill]').style.width=progress+'%';const bar=this.root.querySelector('.convoy-route');bar.setAttribute('aria-valuenow',Math.round(progress));bar.setAttribute('aria-valuetext',Math.round(progress)+' percent; '+d.completedPickups+' pickups complete; '+d.buses.filter(b=>b.escaped).length+' buses escaped');this.root.dataset.phase=d.phase;
  this.stopMarkers.forEach((node,i)=>{node.classList.toggle('complete',i<d.completedPickups);node.classList.toggle('current',d.phase==='pickup'&&i===d.pickup-1);});
  d.buses.forEach((b,i)=>{const row=this.busRows[i],state=b.destroyed?'LOST':b.escaped?'SAFE':'ABOARD';row.classList.toggle('destroyed',b.destroyed);row.classList.toggle('escaped',b.escaped);row.querySelector('[data-state]').textContent=state;row.querySelector('[data-hp]').textContent='HP '+Math.ceil(b.health)+' / '+b.maxHealth;row.querySelector('[data-passengers]').textContent=b.onboard+' / '+b.capacity+' passengers';const hp=Math.round(b.health/b.maxHealth*100);row.querySelector('em').style.width=hp+'%';row.querySelector('i').setAttribute('aria-valuenow',hp);row.querySelector('i').setAttribute('aria-label','Bus '+(i+1)+' health');const marker=this.busMarkers[i];marker.style.left=Math.max(0,Math.min(100,project(mission.config.map.route,b.position)/mission.length*100))+'%';marker.classList.toggle('destroyed',b.destroyed);marker.classList.toggle('escaped',b.escaped);marker.title='Bus '+(i+1)+' · '+state;});text('detail',d.terminal?'Saved '+d.result.saved+' · killed '+d.result.killed+' · left behind '+d.result.leftBehind:'Pickups '+d.completedPickups+'/2 · Passengers score only after their bus exits.');this.root.querySelector('[data-results]').hidden=!d.result;
 }
}
